:root {
  --page-pad: var(--space-32);
  --grid-gap: var(--space-48);
  --accent-brand: #ff6633;
  --accent-brand-rgb: 255, 102, 51;
  --space-4: 4px;
  --space-6: 6px;
  --space-8: 8px;
  --space-12: 12px;
  --space-16: 16px;
  --space-20: 20px;
  --space-24: 24px;
  --space-32: 32px;
  --space-40: 40px;
  --space-48: 48px;
  --space-64: 64px;
  --radius-pill: 999px;
  --glass-radius: 16px;
  --radius-modal: calc(var(--glass-radius) * 2);
  --glass-surface-rgb: 96, 98, 100;
  --glass-bg: rgba(var(--glass-surface-rgb), 0.2);
  --glass-card-bg: rgba(var(--glass-surface-rgb), 0.2);
  --glass-compact-surface-rgb: 24, 24, 24;
  --glass-compact-bg: rgba(var(--glass-compact-surface-rgb), 0.2);
  --glass-compact-card-bg: rgba(var(--glass-compact-surface-rgb), 0.2);
  --glass-border: rgba(255, 255, 255, 0.07);
  --glass-border-active: rgba(var(--accent-brand-rgb), 0.72);
  --glass-blur: 16px;
  --modal-pad: var(--space-48);
}

html {
  background: var(--bg-app);
}

body {
  position: relative;
  isolation: isolate;
  background: transparent;
  font-family: Roboto, Arial, sans-serif;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-image: image-set(
    url("./assets/f2-reference-bg.jpg?v=local-retina-2") 1x,
    url("data:image/png;base64,") 2x
  );
  background-position: left center;
  background-size: cover;
  background-repeat: no-repeat;
  filter: none;
}

@supports not (background-image: image-set(url("./assets/f2-reference-bg.jpg") 1x)) {
  body::before {
    background-image: url("data:image/png;base64,");
  }
}

body::after,
.hero::before,
.hero::after,
.scene::before,
.scene::after {
  display: none !important;
  content: none !important;
}

.page-shell {
  position: relative;
  z-index: 1;
  overflow: visible;
}

.hero {
  min-height: 100svh;
  height: 100svh;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: var(--grid-gap);
  align-items: stretch;
  padding: var(--page-pad);
}

.scene {
  position: relative;
  min-height: 0;
  opacity: 1;
  transform: none;
  overflow: visible;
  border-radius: 0;
  background: none !important;
}

.token-card {
  position: absolute;
  z-index: 2;
  display: block !important;
  border-radius: var(--space-8);
  border: 1px solid rgba(255, 255, 255, 0.1);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.018)),
    rgba(17, 17, 17, 0.68);
  box-shadow: 0 18px 56px rgba(0, 0, 0, 0.44);
  backdrop-filter: blur(18px);
}

.token-card--colors {
  top: 28%;
  left: var(--space-48);
  width: clamp(260px, 26vw, 380px);
  height: 76px;
  display: flex !important;
  align-items: center;
  gap: var(--space-12);
  padding: var(--space-16);
}

.token-card--colors span {
  width: 42px;
  height: 42px;
  border-radius: var(--space-12);
}

.token-card--colors span:nth-child(3) {
  background: #242526;
}

.token-card--type {
  top: 43%;
  left: var(--space-48);
  width: clamp(330px, 34vw, 510px);
  height: 104px;
  padding: var(--space-16) var(--space-24);
}

.token-card--type b {
  margin-right: var(--space-24);
  font-size: 42px;
  line-height: 44px;
  font-weight: 700;
}

.token-card--type span {
  height: 7px;
  margin: var(--space-8) 0 0 calc(var(--space-48) * 2 + var(--space-24));
  border-radius: var(--radius-pill);
}

.token-card--type span:last-child {
  width: 48%;
}

.content-card {
  position: relative;
  width: 100%;
  max-width: none;
  min-height: 0;
  max-height: none;
  justify-self: stretch;
  align-self: stretch;
  overflow: hidden;
  padding: var(--space-32);
  border-radius: var(--glass-radius);
  border: 1px solid var(--glass-border);
  background: var(--glass-bg);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.06),
    0 24px 80px rgba(0, 0, 0, 0.52);
  backdrop-filter: blur(var(--glass-blur)) saturate(1.24);
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(1.24);
}

.brand span,
.summary,
.button,
.meta-grid dd,
.updates__header p:last-child,
.update-card p {
  font-family: Roboto, Arial, sans-serif;
  font-size: 17px;
  line-height: 22px;
  font-weight: 400;
}

.brand span,
.button--primary {
  color: #fff;
}

.version,
.meta-grid dd {
  color: var(--text-secondary);
}

.version {
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  padding: 0 var(--space-16);
  border-radius: var(--radius-pill);
  font-size: 14px;
  line-height: 18px;
  font-weight: 400;
}

.hero-copy {
  margin-top: calc(var(--space-48) * 2);
}

.eyebrow,
.meta-grid dt {
  color: var(--accent-brand);
  font-family: Roboto, Arial, sans-serif;
  font-size: 11px;
  line-height: 14px;
  font-weight: 400;
  letter-spacing: 0;
  text-transform: uppercase;
}

.eyebrow {
  margin: 0 0 var(--space-16);
}

h1 {
  max-width: 760px;
  margin: 0;
  font-family: Roboto, Arial, sans-serif;
  font-size: clamp(64px, 6.2vw, 102px);
  line-height: 0.96;
  font-weight: 900;
  letter-spacing: 0;
  text-transform: uppercase;
  -webkit-text-stroke: 1.2px rgba(255, 255, 255, 0.96);
  text-shadow:
    0.016em 0 0 rgba(255, 255, 255, 0.9),
    -0.016em 0 0 rgba(255, 255, 255, 0.9);
}

.summary {
  max-width: 620px;
  margin: var(--space-24) 0 0;
  color: var(--text-secondary);
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-12);
  margin-top: var(--space-32);
}

.button {
  position: relative;
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-8);
  border-radius: var(--radius-pill);
  padding: 0 var(--space-24);
  overflow: visible;
  isolation: isolate;
  transform: translateY(0);
  transition:
    border-color 180ms ease,
    background 180ms ease,
    color 180ms ease,
    box-shadow 180ms ease,
    transform 180ms ease;
}

.button::before {
  content: "";
  position: absolute;
  left: 10%;
  right: 10%;
  bottom: calc(var(--space-8) * -1);
  height: 18px;
  z-index: -1;
  border-radius: var(--radius-pill);
  background: rgba(var(--accent-brand-rgb), 0.16);
  filter: blur(16px);
  opacity: 0;
  transition: opacity 180ms ease, transform 180ms ease;
}

.button:hover,
.button:focus-visible {
  transform: translateY(-2px);
}

.button:hover::before,
.button:focus-visible::before {
  opacity: 1;
  transform: translateY(2px);
}

.button svg {
  width: 20px;
  height: 20px;
  color: currentColor;
}

.button--primary {
  background: var(--accent-brand);
  border: 1px solid var(--accent-brand);
  color: #fff;
  box-shadow:
    0 10px 18px rgba(0, 0, 0, 0.22);
}

.button--primary:hover,
.button--primary:focus-visible {
  box-shadow:
    0 16px 28px rgba(0, 0, 0, 0.3),
    0 8px 18px rgba(var(--accent-brand-rgb), 0.12);
}

.button--secondary {
  border: 1px solid rgba(var(--accent-brand-rgb), 0.64);
  background: rgba(24, 24, 24, 0.48);
  color: var(--accent-brand);
  box-shadow: none;
}

.button--secondary::before {
  display: none;
}

.button--secondary:hover,
.button--secondary:focus-visible {
  border-color: rgba(var(--accent-brand-rgb), 0.82);
  background: rgba(36, 37, 38, 0.58);
  box-shadow: none;
}

.meta-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-12);
  margin: auto 0 0;
  padding-top: var(--space-32);
}

.meta-grid div {
  min-height: 92px;
  padding: var(--space-16);
  border-radius: calc(var(--glass-radius) / 2);
  border: 1px solid rgba(255, 255, 255, 0.06);
  background: var(--glass-compact-bg);
  backdrop-filter: blur(var(--glass-blur)) saturate(1.24);
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(1.24);
}

.meta-grid dt {
  margin: 0 0 var(--space-12);
}

.meta-grid dd {
  margin: 0;
  color: rgba(255, 255, 255, 0.88);
}

.updates {
  position: relative;
  isolation: isolate;
  align-items: start;
  padding-top: var(--space-24);
  grid-template-columns: minmax(280px, 360px) max-content;
  overflow-x: auto;
  overflow-y: visible;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.22) rgba(255, 255, 255, 0.06);
}

.updates__header {
  position: relative;
  z-index: 1;
  padding: var(--space-48) var(--space-32) 0 0;
  border: 0;
  border-radius: 0;
  background: transparent;
}

.updates__header::before {
  content: "";
  display: block;
  width: calc(var(--space-48) + var(--space-24));
  height: var(--space-4);
  margin: 0 0 var(--space-24);
  border-radius: var(--radius-pill);
  background: var(--accent-brand);
}

.updates__header h2 {
  max-width: 320px;
  font-size: 36px;
  line-height: 42px;
  font-weight: 700;
  letter-spacing: -1px;
}

.updates__header p:last-child {
  max-width: 330px;
}

.update-card {
  position: relative;
  display: block;
  min-width: 320px;
  min-height: 246px;
  border-radius: var(--glass-radius);
  border: 1px solid transparent;
  background: var(--glass-bg);
  backdrop-filter: blur(var(--glass-blur)) saturate(1.24);
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(1.24);
  overflow: visible;
  transform: translateY(0);
  box-shadow: 0 18px 48px rgba(0, 0, 0, 0.34);
  transition:
    border-color 180ms ease,
    box-shadow 180ms ease,
    transform 180ms ease,
    background 180ms ease;
}

.update-card::before,
.log-card::before,
.update-modal__panel::before {
  content: "";
  position: absolute;
  inset: calc(var(--space-16) * -1);
  z-index: -1;
  border-radius: calc(var(--glass-radius) + var(--space-8));
  background:
    radial-gradient(ellipse at 50% 56%, rgba(var(--accent-brand-rgb), 0.18), rgba(var(--accent-brand-rgb), 0.07) 42%, rgba(var(--accent-brand-rgb), 0) 74%);
  filter: blur(20px);
  opacity: 0;
  transition: opacity 180ms ease;
}

.update-card:hover,
.update-card:focus-visible,
.log-card:hover,
.log-card:focus-visible {
  transform: translateY(-4px);
  border-color: var(--glass-border-active);
  box-shadow:
    0 0 0 2px rgba(var(--accent-brand-rgb), 0.64),
    0 24px 54px rgba(0, 0, 0, 0.42),
    0 12px 30px rgba(var(--accent-brand-rgb), 0.1);
}

.update-card:hover::before,
.update-card:focus-visible::before,
.log-card:hover::before,
.log-card:focus-visible::before {
  opacity: 1;
}

.update-card__version {
  font-family: Roboto, Arial, sans-serif;
  font-size: 14px;
  line-height: 18px;
  font-weight: 400;
}

.update-card h3 {
  font-family: Roboto, Arial, sans-serif;
  font-size: 24px;
  line-height: 32px;
  font-weight: 700;
  letter-spacing: -1px;
}

.update-grid {
  position: relative;
  z-index: 1;
  display: flex;
  gap: var(--space-12);
  overflow-x: visible;
  overflow-y: visible;
  margin-left: 0;
  padding: var(--space-24) var(--space-8) var(--space-32) 0;
}

.updates::-webkit-scrollbar {
  height: var(--space-6);
}

.updates::-webkit-scrollbar-track {
  background: rgba(255, 255, 255, 0.06);
  border-radius: var(--radius-pill);
  backdrop-filter: blur(12px);
}

.updates::-webkit-scrollbar-thumb {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.28), rgba(255, 255, 255, 0.14));
  border-radius: var(--radius-pill);
  border: 1px solid rgba(255, 255, 255, 0.12);
}

.update-card {
  flex: 0 0 min(340px, 82vw);
}

.log-card--current {
  border-color: rgba(var(--accent-brand-rgb), 0.46);
}

.update-card--show-all {
  min-width: 168px;
  min-height: 246px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-color: rgba(var(--accent-brand-rgb), 0.4);
  color: #fff;
}

.update-card--show-all span {
  font-family: Roboto, Arial, sans-serif;
  font-size: 24px;
  line-height: 32px;
  font-weight: 700;
  letter-spacing: -1px;
}

.page-shell--log {
  min-height: 100vh;
}

.log-hero {
  min-height: auto;
  padding: var(--space-48) calc(var(--space-48) * 1.5) var(--space-24);
  overflow: visible;
}

.log-hero::before {
  display: none;
  content: none;
}

.log-heading {
  max-width: 760px;
  margin-top: calc(var(--space-48) * 2);
}

.log-heading h1 {
  font-size: clamp(52px, 6vw, 92px);
  line-height: 0.96;
  font-weight: 900;
}

.log-heading .summary {
  max-width: 620px;
}

.log-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-16);
  padding: var(--space-24) calc(var(--space-48) * 1.5) calc(var(--space-48) * 1.5);
}

.log-card {
  position: relative;
  display: block;
  min-height: 280px;
  padding: var(--space-24);
  border-radius: var(--glass-radius);
  border: 1px solid transparent;
  background: var(--glass-bg);
  backdrop-filter: blur(var(--glass-blur)) saturate(1.24);
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(1.24);
  transform: translateY(0);
  overflow: visible;
  box-shadow: 0 18px 48px rgba(0, 0, 0, 0.34);
  transition:
    border-color 180ms ease,
    box-shadow 180ms ease,
    transform 180ms ease,
    background 180ms ease;
}

.log-card__meta {
  display: flex;
  gap: var(--space-12);
  align-items: center;
}

.log-card__meta strong {
  font-family: Roboto, Arial, sans-serif;
  font-size: 28px;
  line-height: 32px;
  font-weight: 700;
}

.log-card__body h2 {
  margin-top: var(--space-48);
  font-family: Roboto, Arial, sans-serif;
  font-size: 24px;
  line-height: 32px;
  font-weight: 700;
  letter-spacing: -1px;
}

.log-card__body p {
  margin-top: var(--space-12);
  font-family: Roboto, Arial, sans-serif;
  font-size: 17px;
  line-height: 22px;
  font-weight: 400;
}

.modal-open {
  overflow: hidden;
}

.update-modal[hidden] {
  display: none;
}

.update-modal {
  position: fixed;
  inset: 0;
  z-index: 20;
  display: grid;
  place-items: center;
  padding: var(--page-pad);
  opacity: 0;
  transition: opacity 180ms ease;
}

.update-modal.is-open {
  opacity: 1;
}

.update-modal__scrim {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.56);
}

.update-modal__panel {
  position: relative;
  width: min(720px, 100%);
  display: grid;
  gap: var(--space-24);
  padding: var(--modal-pad);
  border-radius: var(--glass-radius);
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: var(--glass-bg);
  color: #fff;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.06),
    0 28px 80px rgba(0, 0, 0, 0.58);
  backdrop-filter: blur(var(--glass-blur)) saturate(1.24);
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(1.24);
  transform: translateY(10px) scale(0.98);
  transition: transform 180ms ease;
  outline: none;
}

.update-modal.is-open .update-modal__panel {
  transform: translateY(0) scale(1);
}

.update-modal__close {
  position: absolute;
  top: var(--space-16);
  right: var(--space-16);
  width: 40px;
  height: 40px;
  display: inline-grid;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: var(--radius-pill);
  background: rgba(var(--glass-surface-rgb), 0.42);
  color: rgba(255, 255, 255, 0.82);
  cursor: pointer;
}

.update-modal__close svg {
  width: 20px;
  height: 20px;
}

.update-modal__version {
  min-height: 36px;
  width: max-content;
  display: inline-flex;
  align-items: center;
  padding: 0 var(--space-16);
  border-radius: var(--radius-pill);
  background: rgba(var(--accent-brand-rgb), 0.14);
  color: var(--accent-brand);
  font-family: Roboto, Arial, sans-serif;
  font-size: 17px;
  line-height: 22px;
}

.update-modal__content {
  display: grid;
  gap: var(--space-8);
}

.update-modal h2 {
  max-width: 560px;
  margin: 0;
  font-family: Roboto, Arial, sans-serif;
  font-size: clamp(32px, 4vw, 48px);
  line-height: 1.05;
  font-weight: 900;
  letter-spacing: -1px;
}

.update-modal p,
.update-modal li {
  font-family: Roboto, Arial, sans-serif;
  font-size: 17px;
  line-height: 24px;
  color: var(--text-secondary);
}

.update-modal p {
  max-width: 560px;
  margin: 0;
}

.update-modal__section-label {
  display: block;
  margin-top: calc(var(--modal-pad) - var(--space-8));
  color: var(--accent-brand);
  font-family: Roboto, Arial, sans-serif;
  font-size: 10px;
  line-height: 12px;
  font-weight: 400;
  text-transform: uppercase;
}

.update-modal__list {
  display: grid;
  gap: var(--space-6);
  margin: 0;
  padding: 0;
  list-style: none;
}

.update-modal li {
  position: relative;
  padding-left: var(--space-16);
}

.update-modal li::before {
  content: "";
  position: absolute;
  left: 0;
  top: var(--space-8);
  width: 5px;
  height: 5px;
  border-radius: var(--radius-pill);
  background: var(--accent-brand);
}

@media (max-height: 820px) and (min-width: 1061px) {
  .hero {
    height: 100svh;
    min-height: 0;
  }

  .content-card {
    padding: var(--space-32);
    border-radius: var(--glass-radius);
  }

  .brand img {
    width: 34px;
    height: 34px;
    border-radius: var(--space-8);
  }

  .hero-copy {
    margin-top: var(--space-48);
  }

  h1 {
    max-width: 760px;
    font-size: clamp(58px, 5.6vw, 84px);
    font-weight: 900;
  }

  .summary {
    margin-top: var(--space-16);
  }

  .actions {
    margin-top: var(--space-24);
  }

  .meta-grid {
    padding-top: var(--space-24);
  }

  .meta-grid div {
    min-height: 82px;
    padding: var(--space-16);
    border-radius: var(--glass-radius);
  }
}

@media (max-width: 1060px) {
  .hero {
    grid-template-columns: 1fr;
    height: auto;
    min-height: 100svh;
  }

  .scene {
    display: none;
  }

  .content-card {
    min-height: calc(100svh - var(--page-pad) * 2);
  }

  .meta-grid {
    grid-template-columns: 1fr;
  }

  .updates {
    grid-template-columns: 1fr;
    overflow-x: visible;
    padding-inline: var(--page-pad);
  }

  .updates__header {
    padding: 0;
  }

  .update-grid {
    flex-direction: column;
    width: 100%;
    gap: var(--space-12);
    padding: var(--space-4) 0 0;
  }

  .update-card {
    width: 100%;
    min-width: 0;
    min-height: 0;
    flex: none;
    padding: var(--space-24);
  }

  .update-card--show-all {
    min-height: 88px;
  }

  .update-modal {
    align-items: end;
    padding: var(--space-16);
  }

  .update-modal__panel {
    padding: var(--space-24);
  }

  .log-list {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  :root {
    --page-pad: var(--space-16);
  }

  .content-card {
    padding: var(--space-24);
  }

  .brand img {
    width: 48px;
    height: 48px;
  }

  .brand span,
  .summary,
  .button,
  .meta-grid dd,
  .updates__header p:last-child,
  .update-card p {
    font-size: 17px;
    line-height: 22px;
  }

  .hero-copy {
    margin-top: var(--space-48);
  }

  h1 {
    max-width: 100%;
    font-size: clamp(44px, 14vw, 56px);
    line-height: 0.98;
  }

  .actions {
    display: grid;
    gap: var(--space-12);
  }

  .button {
    width: 100%;
  }
}

/* Final stable layer: this must stay last so older base rules cannot
   override the approved layout. */

.token-card--colors {
  display: flex !important;
  align-items: center;
  justify-content: flex-start;
  gap: var(--space-12);
  padding: var(--space-16);
}

.token-card--colors span {
  flex: 0 0 42px;
  width: 42px;
  height: 42px;
}

.token-card--colors span:nth-child(1) {
  background: var(--accent-brand);
}

.token-card--colors span:nth-child(2) {
  background: var(--accent-brand);
}

.token-card--colors span:nth-child(3) {
  background: var(--surface-raised);
}

.token-card--colors span:nth-child(4) {
  background: var(--text-secondary);
}

.token-card--colors span:nth-child(5) {
  background: var(--text-primary);
}

.token-card--type {
  display: grid !important;
  grid-template-columns: auto 1fr;
  align-items: center;
  column-gap: var(--space-24);
  row-gap: var(--space-8);
}

.token-card--type b {
  grid-row: 1 / 3;
  margin: 0;
}

.token-card--type span {
  margin: 0;
}

.content-card,
.update-card,
.log-card,
.update-modal__panel {
  background: var(--glass-card-bg);
  backdrop-filter: blur(var(--glass-blur)) saturate(1.24);
  -webkit-backdrop-filter: blur(var(--glass-blur)) saturate(1.24);
}

.meta-grid div {
  background: var(--glass-compact-card-bg);
  border-radius: calc(var(--glass-radius) / 2);
  padding: var(--space-16);
}

.updates {
  display: block;
  position: relative;
  isolation: isolate;
  padding: var(--space-64) 0 var(--space-64) var(--space-48);
  overflow: hidden;
}

.updates .update-grid {
  display: flex;
  flex-direction: row;
  align-items: stretch;
  gap: var(--space-12);
  width: 100%;
  margin: 0;
  padding: var(--space-24) var(--space-48) var(--space-32) 0;
  overflow-x: auto;
  overflow-y: visible;
  scroll-snap-type: x proximity;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.22) rgba(255, 255, 255, 0.06);
}

.updates .update-grid::-webkit-scrollbar {
  height: var(--space-6);
}

.updates .update-grid::-webkit-scrollbar-track {
  border-radius: var(--radius-pill);
  background: rgba(255, 255, 255, 0.06);
}

.updates .update-grid::-webkit-scrollbar-thumb {
  border-radius: var(--radius-pill);
  background: rgba(255, 255, 255, 0.2);
}

.updates__header {
  flex: 0 0 360px;
  min-width: 0;
  min-height: 246px;
  padding: var(--space-48) var(--space-32) var(--space-24) 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  scroll-snap-align: start;
}

.updates__header h2 {
  margin: 0;
  width: 100%;
  max-width: none;
  white-space: nowrap;
  font-size: 36px;
  line-height: 42px;
  font-weight: 700;
  letter-spacing: -1px;
}

.updates__header p:last-child {
  width: 100%;
  max-width: none;
  margin-top: var(--space-24);
  font-size: 17px;
  line-height: 22px;
}

.update-card {
  box-sizing: border-box;
  flex: 0 0 340px;
  min-width: 340px;
  min-height: 246px;
  padding: var(--space-32);
  display: flex;
  flex-direction: column;
  scroll-snap-align: start;
}

.update-card__version {
  align-self: flex-start;
  min-height: var(--space-32);
  display: inline-flex;
  align-items: center;
  padding: 0 var(--space-12);
  border-radius: var(--radius-pill);
}

.update-card h3 {
  margin: calc(var(--space-48) + var(--space-16)) 0 0;
}

.update-card p {
  margin: var(--space-16) 0 0;
}

.update-card--show-all {
  align-items: center;
  justify-content: center;
}

.update-card--show-all span {
  font-family: Roboto, Arial, sans-serif;
  font-size: 24px;
  line-height: 32px;
  font-weight: 700;
}

.update-modal {
  padding: var(--space-32);
}

.update-modal__panel {
  border-radius: var(--radius-modal);
  padding: var(--space-48);
}

.update-modal__intro {
  margin-top: var(--space-16);
}

.update-modal__section {
  margin-top: var(--space-48);
}

.update-modal__section h3 {
  margin: 0 0 var(--space-16);
}

.update-modal__section li + li {
  margin-top: var(--space-12);
}

@media (max-width: 1060px) {
  .updates {
    padding: var(--space-48) var(--page-pad);
    overflow: visible;
  }

  .updates .update-grid {
    flex-direction: column;
    gap: var(--space-16);
    padding: 0;
    overflow: visible;
    scroll-snap-type: none;
  }

  .updates__header {
    flex: none;
    min-height: 0;
    padding: 0 0 var(--space-16);
  }

  .update-card {
    flex: none;
    width: 100%;
    min-width: 0;
    min-height: 0;
    padding: var(--space-24);
  }
}

@media (max-width: 640px) {
  .update-modal {
    padding: var(--space-16);
  }

  .update-modal__panel {
    padding: var(--space-24);
    border-radius: var(--glass-radius);
  }
}
